<script setup lang="ts">import {computed,onMounted,reactive,ref} from 'vue';import {api,day,fmt,json,today} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import EmptyState from '@/components/EmptyState.vue';import {Plus} from 'lucide-vue-next';const items=ref<any[]>([]),products=ref<any[]>([]),sites=ref<any[]>([]),open=ref(false),detail=ref<any>(),editing=ref<any>(),form=reactive<any>({}),filters=reactive({siteId:'',productId:'',start:'',end:''});const site=computed(()=>sites.value.find(x=>x.id==form.siteId));const cny=computed(()=>Number(form.originalAmount||0)*Number(site.value?.exchangeRate||0));async function load(){items.value=await api('/orders?'+new URLSearchParams(filters as any).toString())}onMounted(async()=>{[products.value,sites.value]=await Promise.all([api('/products'),api('/sites')]);load()});function show(x?:any){editing.value=x;Object.assign(form,x?{...x,saleDate:String(x.saleDate).slice(0,10)}:{saleDate:today(),orderNo:'',lineNo:1,siteId:sites.value[0]?.id,productId:products.value[0]?.id,quantity:1,originalAmount:0,otherFees:0,notes:''});open.value=true}async function save(){try{await api(editing.value?`/orders/${editing.value.id}`:'/orders',json(editing.value?'PATCH':'POST',form));open.value=false;load()}catch(e:any){alert(e.message)}}async function del(x:any){if(confirm('删除订单将释放库存并重算后续 FIFO，确定继续？'))try{await api(`/orders/${x.id}`,{method:'DELETE'});load()}catch(e:any){alert(e.message)}}</script>
<template><PageHeader title="售出订单" subtitle="到账按站点汇率转换，成本来自采购批次 FIFO"><el-button type="primary" :icon="Plus" @click="show()">新增订单</el-button></PageHeader><el-card shadow="never" class="mb-4"><div class="flex flex-wrap gap-3"><el-date-picker v-model="filters.start" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="filters.end" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-select v-model="filters.siteId" clearable placeholder="全部站点" class="!w-44"><el-option v-for="s in sites" :key="s.id" :label="s.name" :value="String(s.id)"/></el-select><el-select v-model="filters.productId" clearable filterable placeholder="全部商品" class="!w-52"><el-option v-for="p in products" :key="p.id" :label="p.name" :value="String(p.id)"/></el-select><el-button type="primary" plain @click="load">应用筛选</el-button></div></el-card><el-card shadow="never"><el-table :data="items" stripe empty-text="暂无售出订单"><el-table-column label="日期 / 订单" min-width="150"><template #default="{row}">{{day(row.saleDate)}}<div class="text-xs text-slate-400">{{row.orderNo}} · 行{{row.lineNo}}</div></template></el-table-column><el-table-column label="站点" min-width="150"><template #default="{row}">{{row.site.name}}<div class="text-xs text-slate-400">汇率 {{fmt(row.exchangeRateSnapshot,4)}}</div></template></el-table-column><el-table-column label="商品" min-width="180"><template #default="{row}">{{row.product.name}}<div class="text-xs text-slate-400">{{row.product.sku}}</div></template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column label="原币到账" min-width="120"><template #default="{row}">{{row.currencySnapshot}} {{fmt(row.originalAmount)}}</template></el-table-column><el-table-column label="CNY 到账"><template #default="{row}">¥ {{fmt(row.cnyAmount)}}</template></el-table-column><el-table-column label="综合成本"><template #default="{row}">¥ {{fmt(row.comprehensiveCost)}}</template></el-table-column><el-table-column label="毛利 / 毛利率" min-width="130"><template #default="{row}"><el-text :type="Number(row.grossProfit)>=0?'success':'danger'"><b>¥ {{fmt(row.grossProfit)}}</b> · {{row.grossMargin==null?'—':fmt(Number(row.grossMargin)*100)+'%'}}</el-text></template></el-table-column><el-table-column label="操作" fixed="right" width="180"><template #default="{row}"><el-button link @click="detail=row">详情</el-button><el-button link type="primary" @click="show(row)">编辑</el-button><el-button link type="danger" @click="del(row)">删除</el-button></template></el-table-column></el-table></el-card><AppModal :open="open" :title="editing?'编辑售出订单':'新增售出订单'" width="760px" @close="open=false"><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-4 sm:grid-cols-2"><el-form-item label="日期" required><el-date-picker v-model="form.saleDate" type="date" value-format="YYYY-MM-DD" class="!w-full"/></el-form-item><div class="grid grid-cols-3 gap-3"><el-form-item label="订单号" required class="col-span-2"><el-input v-model="form.orderNo"/></el-form-item><el-form-item label="行号"><el-input-number v-model="form.lineNo" :min="1" class="!w-full"/></el-form-item></div><el-form-item label="站点" required><el-select v-model="form.siteId" class="w-full"><el-option v-for="s in sites.filter(x=>x.active)" :key="s.id" :label="`${s.name} · ${s.currency}`" :value="s.id"/></el-select></el-form-item><el-form-item label="产品 / SKU" required><el-select v-model="form.productId" filterable class="w-full"><el-option v-for="p in products" :key="p.id" :label="`${p.name} · ${p.sku}`" :value="p.id"/></el-select></el-form-item><el-form-item label="数量" required><el-input-number v-model="form.quantity" :min="1" class="!w-full" controls-position="right"/></el-form-item><el-form-item :label="`原币到账金额（${site?.currency||'—'}）`"><el-input-number v-model="form.originalAmount" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="订单其他费用（CNY）"><el-input-number v-model="form.otherFees" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-alert :closable="false" type="success" show-icon><template #title>预计 CNY 到账：¥ {{fmt(cny)}}（汇率 {{fmt(site?.exchangeRate,4)}}）</template></el-alert></div><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item><div class="flex justify-end gap-2"><el-button @click="open=false">取消</el-button><el-button type="primary" native-type="submit">保存并分配库存</el-button></div></el-form></AppModal><AppModal :open="!!detail" title="FIFO 成本明细" width="760px" @close="detail=null"><div v-if="detail"><el-descriptions :column="3" border class="mb-5"><el-descriptions-item label="产品成本">¥ {{fmt(detail.goodsCost)}}</el-descriptions-item><el-descriptions-item label="包材成本">¥ {{fmt(detail.packagingCost)}}</el-descriptions-item><el-descriptions-item label="订单毛利"><b>¥ {{fmt(detail.grossProfit)}}</b></el-descriptions-item></el-descriptions><el-table :data="detail.allocations" stripe><el-table-column label="采购批次"><template #default="{row}">{{row.batch.purchase.purchaseOrderNo}}<div class="text-xs text-slate-400">{{day(row.batch.purchase.purchaseDate)}}</div></template></el-table-column><el-table-column prop="quantity" label="分配数量"/><el-table-column label="产品单价"><template #default="{row}">¥ {{fmt(row.productUnitCostSnapshot)}}</template></el-table-column><el-table-column label="包材单价"><template #default="{row}">¥ {{fmt(row.packagingUnitCostSnapshot)}}</template></el-table-column><el-table-column label="成本小计"><template #default="{row}"><b>¥ {{fmt(row.totalCost)}}</b></template></el-table-column></el-table></div></AppModal></template>
